def _ref(n: int) -> int:
    # Obviously-correct iterative reference for standard Fibonacci:
    # F(0)=0, F(1)=1, F(n)=F(n-1)+F(n-2).
    # Pinned by spec examples: F(1)=1, F(8)=21, F(10)=55.
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

